import { FilterRegistry } from 'domain/Filter';
import type { FilterForm } from 'models/Filters';

/**
 * Builds the query string for Commercial Results → Performance Tool navigation.
 * Preserves geographic/time/brand context; forces All Brands grouping so PT does
 * not default to Portfolio (unavailable for some countries). CR-only dimensions
 * (sku, region, channel, etc.) must not leak into PT.
 */
export const buildCommercialResultsToPerformanceToolFilterQuery = (
  applied: FilterForm,
): string =>
  FilterRegistry.buildFilterQueryString(
    {
      zone: applied.zone,
      country: applied.country,
      periods: applied.periods,
      brands: applied.brands,
      sub_brands: applied.sub_brands,
    },
    {
      kpis: 'volume',
      growth_levers: 'All',
      brand_filter_groupings: 'All Brands',
    },
  );
